launch:
{
  // Developers register every runnable command here.
  "version": "0.2.0",
  "configurations": [
    { "name": "📦️build-report📋️owner🟦️", "type": "node-terminal", "request": "launch", "command": "bun nx run @semio-tech/owner:build-report", "cwd": "${workspaceFolder}", "presentation": { "group": "4_build", "order": 1 } },
    { "name": "🛠️dev📋️report", "type": "node-terminal", "request": "launch", "command": "bun nx run workspace:dev -- report", "cwd": "${workspaceFolder}", "env": { "S_OS_PORT": "6001", "SEMIO_ARTIFACTS": "${workspaceFolder}/artifacts" }, "presentation": { "group": "3_dev", "order": 2 } },
    { "name": "🧿️snapshot", "type": "node-terminal", "request": "launch", "command": "NX_DAEMON=false bun '${workspaceFolder}/node_modules/nx/dist/bin/nx.js' run workspace:test", "cwd": "${workspaceFolder}", "presentation": { "group": "9_gates" } },
    { "name": "🚀️publish-report", "type": "node-terminal", "request": "launch", "command": "bun nx run @semio-tech/owner:publish-report -- ${input:channel}", "cwd": "${workspaceFolder}" },
    { "name": "🎯️pick-project", "type": "node-terminal", "request": "launch", "command": "bun nx run ${input:project}:build", "cwd": "${workspaceFolder}" },
    { "name": "🪲️attach", "type": "lldb", "request": "attach", "pid": "${command:pickProcess}" }, /* not a terminal command */
  ],
  "compounds": [
    { "name": "🧭️compound📋️report", "configurations": ["🛠️dev📋️report", "📦️build-report📋️owner🟦️"], "stopAll": true, "presentation": { "group": "3_dev" } },
    { "name": "🧭️compound🎯️unresolved", "configurations": ["🛠️dev📋️report", "🎯️pick-project"] },
  ],
  "inputs": [
    { "id": "channel", "type": "promptString", "description": "Release channel", "default": "preview" },
    { "id": "project", "type": "pickString", "description": "Project", "options": ["@semio-tech/owner"] },
  ],
}
